pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 helperExtraGas) public {
        amount = bound(amount, 1, 1 ether);
        helperExtraGas = bound(helperExtraGas, 0, 100000);

        GreedyFallback helper = new GreedyFallback(helperExtraGas);

        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok);

        vm.prank(address(this));

        bool outerOk;
        try c.sendMoney(address(helper), amount, "0xdead") {
            outerOk = true;
        } catch {
            outerOk = false;
        }

        assertTrue(outerOk);
    }
}

contract GreedyFallback {
    uint256 public loops;
    constructor(uint256 extra) payable {
        loops = extra;
    }
    fallback() external payable {
        for (uint256 i = 0; i < loops; ++i) {
            assembly { let x := mul(i, 2) }
        }
    }
}
